 StackPanel wifiContent=new(),pingResults=new();TextBlock pingResult=new();Border toolsPanel=new();Button routerTab=new();string? selectedWifi;
 void InitializeTools(){
  var tabs=(Grid)PassTab.Parent;tabs.ColumnDefinitions.Add(new());var tabCopy=new StackPanel{Orientation=Orientation.Horizontal};tabCopy.Children.Add(ToolIcon("RouterIcon",17));tabCopy.Children.Add(new TextBlock{Text="Router",Margin=new Thickness(7,0,0,0),VerticalAlignment=VerticalAlignment.Center});routerTab.Content=tabCopy;routerTab.Style=(Style)FindResource("QuietButton");routerTab.Padding=new Thickness(10);Grid.SetColumn(routerTab,2);tabs.Children.Add(routerTab);routerTab.Click+=(_,_)=>SelectTools();
  var cards=new StackPanel();toolsPanel.Child=cards;toolsPanel.Visibility=Visibility.Collapsed;BodyContent.Children.Add(toolsPanel);
  var ping=ToolCard("Ping Test","Test 15 EU Gaming Servers","GlobeIcon");var test=ToolButton("Run test",ping);test.Click+=async(_,_)=>await Run(async()=>{Status.Text="Testing 15 servers…";Empty(pingResults,"Testing 15 servers…");using var stream=typeof(MainWindow).Assembly.GetManifestResourceStream("RayWRT.Diagnostics")!;using var reader=new StreamReader(stream);SetPingResult(RouterTools.Ping(await Command("sh -c "+Quote(await reader.ReadToEndAsync())+" raywrt run")));Status.Text="Diagnostic complete · 15 targets tested";});ping.Children.Add(pingResults);Empty(pingResults,"Run a test to measure ping and replies.");cards.Children.Add(WrapTool(ping));
